package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class AnnotationTests {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static FlowEngine.Runner run(Document d){FlowEngine.Runner r=new FlowEngine.Runner(d);for(int i=0;i<5000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++)r.step();check(r.state==FlowEngine.State.COMPLETED,"Execution completes: "+r.errorMessage);return r;}
 static List<Node> notes(Document d){List<Node> result=new ArrayList<>();for(Document g:FlowFunctionEditing.graphs(d))for(Node n:g.nodes)if(n.kind==NOTE)result.add(n);return result;}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),production=root.resolve("../frociart-v1-capabilities/android/app/src/main/assets");String[] texts={"","Spiega la logica del ciclo.\nNessuna variabile viene modificata.","STAMPA 1/0; VAI A B1; </script><img src=x>","Virgolette \" + \\u000a Runtime.exec() //\n🐢\tè",String.join("",Collections.nCopies(4096,"a"))};int at=0;
  for(String text:texts){Document d=FlowPseudocode.decode("x=2\nSTAMPA x");FlowEngine.Runner initial=run(d);Node note=new Node(NOTE,text,900,120);d.nodes.add(note);FlowAnnotations.promote(d);check(d.version==4,"Promotes format 4");String before=FlowCodec.encode(d);for(FlowEngine.Issue issue:FlowEngine.validate(d))check(!note.id.equals(issue.nodeId),"Note has no execution diagnostics");FlowEngine.Runner executed=run(d);check(executed.outputText().equals(initial.outputText())&&executed.steps==initial.steps&&executed.variables.size()==initial.variables.size(),"No execution, steps or variables from documentation");
   FlowSource.Program program=FlowSource.compile(d);check(program.canGenerate()&&program.scopes.get(0).notes.size()==1&&program.scopes.get(0).notes.get(0).text.equals(text),"Immutable note text");for(FlowSource.Block b:program.scopes.get(0).blocks)check(b.kind!=NOTE,"Note outside executable IR");Document decoded=FlowPseudocode.decode(FlowPseudocode.encode(d));check(notes(decoded).get(0).text.equals(text)&&run(decoded).outputText().equals(executed.outputText()),"Pseudocode preserves text and behavior");check(FlowCodec.encode(d.copy()).equals(before),"Native clone stable");FlowAutoLayout.apply(d);check(note.x==900&&note.y==120,"Auto arrange preserves note position");d=FlowCodec.decode(before);FlowgorithmExport.Result fprg=FlowgorithmExport.analyze(d);check(fprg.canExport(),"FPRG export notes");Document imported=FlowgorithmImport.decode(fprg.xml);boolean found=false;for(Node n:notes(imported))found|=text.equals(n.text);check(found&&run(imported).outputText().equals(executed.outputText()),"FPRG standalone comment and runtime");
   FlowSourceText py=FlowPython.generate(program,new String(Files.readAllBytes(production.resolve("PythonRuntime.py")),StandardCharsets.UTF_8)),java=FlowJava.generate(program,new String(Files.readAllBytes(production.resolve("JavaRuntime.txt")),StandardCharsets.UTF_8),"AndroidAnnotationProgram"+at);check(!py.forBlock(null,note.id).isEmpty()&&!java.forBlock(null,note.id).isEmpty(),"Source origins navigate to free note");Files.write(root.resolve("android-note-"+at+".py"),py.text.getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("AndroidAnnotationProgram"+at+".java"),java.text.getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("android-note-"+at+".frociart"),before.getBytes(StandardCharsets.UTF_8));check(FlowCodec.encode(d).equals(before),"Read only conversions stable");Document pc=FlowCodec.decode(new String(Files.readAllBytes(root.resolve("pc-note-"+at+".frociart")),StandardCharsets.UTF_8));check(notes(pc).get(0).text.equals(text)&&run(pc).outputText().equals("2"),"PC document interoperable");at++;
  }
  Document function=FlowPseudocode.decode("FUNZIONE f(x: INTERO) -> INTERO result\nANNOTAZIONE \"Spiega f\"\nresult=x+1\nFINE FUNZIONE\nANNOTAZIONE \"Spiega il programma\"\nSTAMPA f(2)");check(function.version==4&&function.functions.get(0).body.version==4&&notes(function).size()==2,"Function and main note format");check(run(function).outputText().equals("3"),"Function notes do not execute");check(notes(FlowPseudocode.decode(FlowPseudocode.encode(function))).size()==2,"Function pseudocode note scope");Document library=FlowFunctionTransfer.export(function,function.functions.get(0).id);check(library.version==4&&notes(library).size()==1,"Function library retains note");Document invalid=function.copy();invalid.version=2;boolean rejected=false;try{FlowCodec.encode(invalid);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Reject old format with notes");Node note=notes(function).get(0);function.edges.add(new Edge(function.nodes.get(0).id,note.id,"next"));rejected=false;try{FlowCodec.encode(function);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Reject executable note edge");Document bounded=FlowPseudocode.decode("x=2\nSTAMPA x");Node maximum=new Node(NOTE,String.join("",Collections.nCopies(8192,"\"")),0,0);bounded.nodes.add(maximum);FlowAnnotations.promote(bounded);check(notes(FlowPseudocode.decode(FlowPseudocode.encode(bounded))).get(0).text.equals(maximum.text),"Maximum escaped note pseudocode round trip");FlowgorithmExport.Result safe=FlowgorithmExport.analyze(bounded);boolean found=false;for(Node n:notes(FlowgorithmImport.decode(safe.xml)))found|=n.text.equals(maximum.text);check(safe.canExport()&&found,"Maximum FPRG note text");maximum.text="x f(x) min";Map<String,String> rename=new HashMap<>();rename.put("x","conteggio");for(Node n:bounded.nodes)n.text=FlowDeclaration.rewriteNode(n,n.text,rename);check(maximum.text.equals("x f(x) min")&&run(bounded).outputText().equals("2"),"Variable rename preserves free prose");maximum.text=String.join("",Collections.nCopies(8193,"a"));rejected=false;try{FlowCodec.encode(bounded);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"8193 character note rejected");maximum.text="Nota";maximum.breakpoint=true;rejected=false;try{FlowCodec.encode(bounded);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Note breakpoint rejected");Document nested=FlowPseudocode.decode("FUNZIONE f(x: INTERO) -> INTERO result\nANNOTAZIONE \"Spiega f\"\nresult=x+1\nFINE FUNZIONE\nSTAMPA f(2)");nested.functions.get(0).body.version=1;rejected=false;try{FlowCodec.encode(nested);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Nested old-format note rejected");System.out.println("ANNOTATION_ANDROID_CORE PASS checks="+checks);
 }
}
